import re
import csv

def _get_numbers(contents):
    pattern = re.compile(r'^ (?:\+44\s?\d{4}\s?\d{6}|\d{10})\b$')  # Improved validation for UK phone numbers
    reader = csv.DictReader(
        contents.split('\n'),
        lineterminator='\n',
        quoting=csv.QUOTE_NONE)
    valid, rejects = [], []
    for i, row in enumerate(reader):
        if pattern.match(row['phone']):
            valid.append(row)
        else:
            rejects.append({"line_number": i+2, "phone": row['phone']})
    return {"valid": valid, "rejects": rejects}
